import { mkdir, rm, stat } from "node:fs/promises";
import { dirname } from "node:path";
import { readJsonFile, writeJsonFileAtomic } from "../state/files";
import { resolveStatePath } from "../state/paths";
import { createOnDemandClient, type OnDemandClient } from "../supabase/client";

export const AUTH_REFRESH_MIN_TTL_SECONDS = 15 * 60;
export const USER_PROMPT_REFRESH_THROTTLE_MS = 60 * 60 * 1000;

const AUTH_REFRESH_LOCK_STALE_MS = 30_000;
const DEFAULT_LOCK_RETRY_DELAY_MS = 100;
const MAX_LOCK_ATTEMPTS = 50;

export type AuthRefreshTrigger = "session_start" | "user_prompt_submit";

export interface AuthRefreshCheckState {
  version: 1;
  userPromptSubmitLastCheckedAt?: number;
}

export interface AuthRefreshResult {
  refreshed: boolean;
  status: "checked" | "missing_config_or_auth" | "throttled";
  trigger: AuthRefreshTrigger;
}

interface EnsureAuthSessionFreshOptions {
  createClient?: (options: { refreshMinTtlSeconds: number }) => Promise<OnDemandClient | null>;
  lockRetryDelayMs?: number;
  now?: number;
  throttleMs?: number;
  trigger: AuthRefreshTrigger;
}

export function getAuthRefreshCheckFilePath(): string {
  return resolveStatePath("auth", "refresh-check.json");
}

function getAuthRefreshLockPath(): string {
  return resolveStatePath("auth", "refresh.lock");
}

async function sleep(ms: number): Promise<void> {
  await new Promise((resolve) => setTimeout(resolve, ms));
}

async function loadRefreshCheckState(): Promise<AuthRefreshCheckState> {
  const state = await readJsonFile<unknown>(getAuthRefreshCheckFilePath()).catch(() => null);

  if (!state || typeof state !== "object") {
    return { version: 1 };
  }

  const candidate = state as Partial<AuthRefreshCheckState>;
  return {
    version: 1,
    ...(typeof candidate.userPromptSubmitLastCheckedAt === "number" &&
    Number.isFinite(candidate.userPromptSubmitLastCheckedAt)
      ? { userPromptSubmitLastCheckedAt: candidate.userPromptSubmitLastCheckedAt }
      : {}),
  };
}

async function saveRefreshCheckState(state: AuthRefreshCheckState): Promise<void> {
  await writeJsonFileAtomic(getAuthRefreshCheckFilePath(), state);
}

async function acquireRefreshLock(options: {
  now: () => number;
  retryDelayMs: number;
}): Promise<() => Promise<void>> {
  const lockPath = getAuthRefreshLockPath();
  let attempts = 0;

  while (true) {
    attempts += 1;
    if (attempts > MAX_LOCK_ATTEMPTS) {
      throw new Error("Failed to acquire auth refresh lock");
    }

    try {
      await mkdir(dirname(lockPath), { recursive: true, mode: 0o700 });
      await mkdir(lockPath, { mode: 0o700 });
      return async () => {
        await rm(lockPath, { force: true, recursive: true });
      };
    } catch (error) {
      if ((error as NodeJS.ErrnoException).code !== "EEXIST") {
        throw error;
      }

      const lockStats = await stat(lockPath).catch(() => null);
      if (lockStats && options.now() - lockStats.mtimeMs > AUTH_REFRESH_LOCK_STALE_MS) {
        await rm(lockPath, { force: true, recursive: true }).catch(() => undefined);
        continue;
      }

      await sleep(options.retryDelayMs);
    }
  }
}

export async function ensureAuthSessionFresh(
  options: EnsureAuthSessionFreshOptions,
): Promise<AuthRefreshResult> {
  const now = options.now ?? Date.now();
  const throttleMs = options.throttleMs ?? USER_PROMPT_REFRESH_THROTTLE_MS;
  const trigger = options.trigger;

  const state = await loadRefreshCheckState();
  if (
    trigger === "user_prompt_submit" &&
    state.userPromptSubmitLastCheckedAt !== undefined &&
    now - state.userPromptSubmitLastCheckedAt < throttleMs
  ) {
    return {
      refreshed: false,
      status: "throttled",
      trigger,
    };
  }

  const releaseLock = await acquireRefreshLock({
    now: () => Date.now(),
    retryDelayMs: options.lockRetryDelayMs ?? DEFAULT_LOCK_RETRY_DELAY_MS,
  });

  try {
    const lockedState = await loadRefreshCheckState();
    if (
      trigger === "user_prompt_submit" &&
      lockedState.userPromptSubmitLastCheckedAt !== undefined &&
      now - lockedState.userPromptSubmitLastCheckedAt < throttleMs
    ) {
      return {
        refreshed: false,
        status: "throttled",
        trigger,
      };
    }

    const createClient =
      options.createClient ??
      ((input: { refreshMinTtlSeconds: number }) => createOnDemandClient(input));
    const onDemand = await createClient({
      refreshMinTtlSeconds: AUTH_REFRESH_MIN_TTL_SECONDS,
    });

    if (!onDemand) {
      return {
        refreshed: false,
        status: "missing_config_or_auth",
        trigger,
      };
    }

    await onDemand.dispose();
    if (trigger === "user_prompt_submit") {
      await saveRefreshCheckState({
        ...lockedState,
        userPromptSubmitLastCheckedAt: now,
      });
    }

    return {
      refreshed: true,
      status: "checked",
      trigger,
    };
  } finally {
    await releaseLock();
  }
}
