import { type AuthRefreshTrigger, ensureAuthSessionFresh } from "../auth/refresh";

function parseTrigger(value: string | undefined): AuthRefreshTrigger | null {
  switch (value) {
    case "SessionStart":
      return "session_start";
    case "UserPromptSubmit":
      return "user_prompt_submit";
    default:
      return null;
  }
}

const trigger = parseTrigger(process.argv[2]);

async function main(): Promise<void> {
  if (!trigger) {
    return;
  }

  await ensureAuthSessionFresh({ trigger }).catch(() => undefined);
}

void main();
